mapper.select:
SELECT
FP.FINPROD_NAME assetName ,FP.FINPROD_ID assetCode ,'' assetTerm ,'' vdate ,'' mdate ,'' assetAmt ,'' assetRate ,'02' hasChildren ,CONCAT(IFNULL(FP.FINPROD_ID,'null'),'') childInfo ,'root' parentInfo
'' assetName ,'' assetCode ,FPA.SALE_PERIOD assetTerm ,DATE_FORMAT(FP.VDATE,'%Y-%m-%d') vdate ,DATE_FORMAT(FP.MDATE,'%Y-%m-%d') mdate ,(SELECT SUM((CASE WHEN A.PS ='T02' THEN -1 ELSE 1 END)*A.PRIN_AMT) FROM TRD_PRODUCT_DEAL A WHERE A.FINPROD_ID = FP.FINPROD_ID AND A.IS_CANCEL = 'N' AND A.TRADE_STATUS !='03' AND A.SETTLE_DATE <= STR_TO_DATE(#{qDate},'%Y-%m-%d') ) assetAmt ,ROUND(CCR.YIELD*100,4) assetRate ,'01' hasChildren ,CONCAT(FP.FINPROD_ID,'_') childInfo ,CONCAT(IFNULL(FP.P_FINPROD_ID,'null'),'') parentInfo
FROM FIN_PRODUCT FP LEFT JOIN FIN_CASH_INFO CASH ON CASH.FINPROD_ID = FP.FINPROD_ID AND CASH.CASH_TYPE_1 = '02' AND CASH.CASH_TYPE_2 = 'C02' LEFT JOIN FIN_PRODUCT_ADD FPA ON FPA.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_CASH_CALC_RULE CCR ON CCR.CASH_ID = CASH.CASH_ID WHERE 1=1
AND FP.FINPROD_TYPE2 = #{FINPROD_TYPE2_F27}
AND FP.FINPROD_MARKET_ID = #{finprodMarketId}
AND EXISTS ( SELECT 1 FROM FIN_PRODUCT A WHERE A.P_FINPROD_ID = FP.FINPROD_ID
AND A.VDATE <= STR_TO_DATE(#{qDate},'%Y-%m-%d') AND A.MDATE >= STR_TO_DATE(#{qDate},'%Y-%m-%d')
)
AND FP.P_FINPROD_ID = #{parentId}
